content.query:
let roles = datatable(Service:string)["ai-governance-harness-chat", "ai-governance-harness-mcp"];
let received = union customMetrics, requests, dependencies
| where timestamp {TimeRange}
| where cloud_RoleName in ("ai-governance-harness-chat", "ai-governance-harness-mcp")
| summarize LastReceived=max(timestamp), TelemetryRows=count() by Service=cloud_RoleName;
roles | join kind=leftouter received on Service
| project Service, LastReceived, TelemetryRows=coalesce(TelemetryRows, tolong(0)), Evidence=iff(isnull(LastReceived), "No telemetry in selected range", "Telemetry received; not proof of readiness")
